// Generated by xidl from WebIDL: the plugin's half of the wire.
// See x-idl's `wire` module for the encoding.

/// An object the agent holds, by the handle the plugin gave it; zero is
/// none.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Handle(pub u32);

/// Bytes in the program's memory, which the agent reads where they are.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Bytes {
    pub address: u32,
    pub len: u32,
}

/// Commands, encoded one after another.
#[derive(Default)]
pub struct Encoder {
    pub bytes: Vec<u8>,
}

impl Encoder {
    pub fn new() -> Self {
        Self::default()
    }
    fn begin(&mut self, op: u32) -> usize {
        self.u32(op);
        let at = self.bytes.len();
        self.u32(0);
        at
    }
    fn end(&mut self, at: usize) {
        let len = (self.bytes.len() - at - 4) as u32;
        self.bytes[at..at + 4].copy_from_slice(&len.to_le_bytes());
    }
    pub fn u8(&mut self, v: u8) {
        self.bytes.push(v);
    }
    pub fn u32(&mut self, v: u32) {
        self.bytes.extend_from_slice(&v.to_le_bytes());
    }
}

/// Where the program hands the agent its commands: six words in the
/// program's memory, which the agent serves. `sent` counts the batches
/// handed over and `done` those the agent has run, one in flight at a
/// time, at `address` for `len` bytes; `settled` counts the replies the
/// agent has settled. `wake`, when set, is the address of a word the agent
/// adds one to and notifies after settling one: how a program that waits
/// for replies other than by sleeping on `settled` hears of them.
#[repr(C)]
#[derive(Default)]
pub struct Mailbox {
    pub sent: core::sync::atomic::AtomicI32,
    pub done: core::sync::atomic::AtomicI32,
    pub address: core::sync::atomic::AtomicU32,
    pub len: core::sync::atomic::AtomicU32,
    pub settled: core::sync::atomic::AtomicI32,
    pub wake: core::sync::atomic::AtomicU32,
}

impl Mailbox {
    pub const fn new() -> Self {
        use core::sync::atomic::{AtomicI32, AtomicU32};
        Self {
            sent: AtomicI32::new(0),
            done: AtomicI32::new(0),
            address: AtomicU32::new(0),
            len: AtomicU32::new(0),
            settled: AtomicI32::new(0),
            wake: AtomicU32::new(0),
        }
    }

    /// Hand `batch` to the agent and wait until it has run it. Its bytes,
    /// and any its commands point at, are the program's again after.
    pub fn send(&self, batch: &[u8]) {
        use core::sync::atomic::Ordering::SeqCst;
        if batch.is_empty() {
            return;
        }
        self.address.store(batch.as_ptr() as usize as u32, SeqCst);
        self.len.store(batch.len() as u32, SeqCst);
        let sent = self.sent.fetch_add(1, SeqCst).wrapping_add(1);
        notify(&self.sent);
        loop {
            let done = self.done.load(SeqCst);
            if done == sent {
                return;
            }
            wait(&self.done, done);
        }
    }

    /// Wait until the agent has settled a reply beyond the `seen`th, and
    /// return how many it has settled.
    pub fn wait_settled(&self, seen: i32) -> i32 {
        use core::sync::atomic::Ordering::SeqCst;
        loop {
            let settled = self.settled.load(SeqCst);
            if settled != seen {
                return settled;
            }
            wait(&self.settled, seen);
        }
    }
}

/// Where the agent posts records to the program of its own accord: a ring
/// of `capacity` bytes at `address` in the program's memory. A record is
/// its length, then its bytes, padded to four; a length of `u32::MAX` sends
/// the reader back to the ring's start. The agent writes at `tail` and
/// notifies it; the program reads at `head`. The agent drops, and counts in
/// `dropped`, a record the ring has no room for. Both offsets stay below
/// `capacity`, and `tail` never reaches `head` from behind, so equal means
/// empty.
#[repr(C)]
#[derive(Default)]
pub struct Queue {
    pub tail: core::sync::atomic::AtomicI32,
    pub head: core::sync::atomic::AtomicU32,
    pub address: core::sync::atomic::AtomicU32,
    pub capacity: core::sync::atomic::AtomicU32,
    pub dropped: core::sync::atomic::AtomicU32,
}

impl Queue {
    pub const fn new() -> Self {
        use core::sync::atomic::{AtomicI32, AtomicU32};
        Self {
            tail: AtomicI32::new(0),
            head: AtomicU32::new(0),
            address: AtomicU32::new(0),
            capacity: AtomicU32::new(0),
            dropped: AtomicU32::new(0),
        }
    }

    /// Give the agent `ring` to write to, empty. The program keeps it for as
    /// long as the agent may write, and passes it to `pop`.
    pub fn attach(&self, ring: &mut [u8]) {
        use core::sync::atomic::Ordering::SeqCst;
        self.tail.store(0, SeqCst);
        self.head.store(0, SeqCst);
        self.address
            .store(ring.as_mut_ptr() as usize as u32, SeqCst);
        self.capacity.store((ring.len() & !3) as u32, SeqCst);
    }

    /// Where the agent has written up to: what `wait` takes.
    pub fn tail(&self) -> i32 {
        self.tail.load(core::sync::atomic::Ordering::SeqCst)
    }

    /// The next record's bytes from `ring`, the slice attached, or `None`
    /// while the agent has posted nothing more.
    pub fn pop(&self, ring: &[u8]) -> Option<Vec<u8>> {
        use core::sync::atomic::Ordering::SeqCst;
        let capacity = (self.capacity.load(SeqCst) as usize).min(ring.len());
        loop {
            let tail = self.tail.load(SeqCst) as u32 as usize;
            let head = self.head.load(SeqCst) as usize;
            if head == tail {
                return None;
            }
            let word = |at: usize| {
                ring.get(at..at + 4)
                    .map(|b| u32::from_le_bytes(b.try_into().unwrap()))
            };
            let Some(len) = word(head) else {
                self.head.store(tail as u32, SeqCst);
                return None;
            };
            if len == u32::MAX {
                self.head.store(0, SeqCst);
                continue;
            }
            let start = head + 4;
            let Some(bytes) = ring.get(start..start + len as usize) else {
                // Not a record the agent wrote: give up on what is there.
                self.head.store(tail as u32, SeqCst);
                return None;
            };
            let next = start + (len as usize).next_multiple_of(4);
            self.head
                .store(if next >= capacity { 0 } else { next as u32 }, SeqCst);
            return Some(bytes.to_vec());
        }
    }

    /// The next record that decodes as a `T`, skipping any that do not.
    pub fn take<T: Decode>(&self, ring: &[u8]) -> Option<T> {
        loop {
            let bytes = self.pop(ring)?;
            if let Some(value) = T::decode(&mut Decoder::new(&bytes)) {
                return Some(value);
            }
        }
    }

    /// Sleep until the agent posts beyond `seen`, a `tail()`, or for at most
    /// `timeout` nanoseconds; a negative timeout waits as long as it takes.
    pub fn wait(&self, seen: i32, timeout: i64) {
        wait_for(&self.tail, seen, timeout);
    }
}

/// Sleep while `word` holds `value`: the agent notifies it. On wasm with
/// atomics the including crate enables `stdarch_wasm_atomic_wait`.
#[cfg(all(target_arch = "wasm32", target_feature = "atomics"))]
fn wait(word: &core::sync::atomic::AtomicI32, value: i32) {
    wait_for(word, value, -1);
}

#[cfg(all(target_arch = "wasm32", target_feature = "atomics"))]
fn wait_for(word: &core::sync::atomic::AtomicI32, value: i32, timeout: i64) {
    unsafe { core::arch::wasm32::memory_atomic_wait32(word.as_ptr(), value, timeout) };
}

#[cfg(not(all(target_arch = "wasm32", target_feature = "atomics")))]
fn wait_for(_: &core::sync::atomic::AtomicI32, _: i32, _: i64) {}

#[cfg(all(target_arch = "wasm32", target_feature = "atomics"))]
fn notify(word: &core::sync::atomic::AtomicI32) {
    unsafe { core::arch::wasm32::memory_atomic_notify(word.as_ptr(), u32::MAX) };
}

// Without shared wasm memory no agent can serve the mailbox.
#[cfg(not(all(target_arch = "wasm32", target_feature = "atomics")))]
fn wait(_: &core::sync::atomic::AtomicI32, _: i32) {
    core::hint::spin_loop();
}

#[cfg(not(all(target_arch = "wasm32", target_feature = "atomics")))]
fn notify(_: &core::sync::atomic::AtomicI32) {}

/// A value as the wire encodes it.
pub trait Encode {
    fn encode(&self, e: &mut Encoder);
}

macro_rules! scalars {
    ($($t:ty),*) => {$(
        impl Encode for $t {
            fn encode(&self, e: &mut Encoder) {
                e.bytes.extend_from_slice(&self.to_le_bytes());
            }
        }
        impl Decode for $t {
            fn decode(d: &mut Decoder) -> Option<Self> {
                Some(<$t>::from_le_bytes(d.take(size_of::<$t>())?.try_into().ok()?))
            }
        }
    )*};
}
scalars!(i8, u8, i16, u16, i32, u32, i64, u64, f32, f64);

impl Encode for () {
    fn encode(&self, _: &mut Encoder) {}
}
impl Encode for bool {
    fn encode(&self, e: &mut Encoder) {
        e.u8(u8::from(*self));
    }
}
impl Encode for String {
    fn encode(&self, e: &mut Encoder) {
        e.u32(self.len() as u32);
        e.bytes.extend_from_slice(self.as_bytes());
    }
}
impl Encode for Handle {
    fn encode(&self, e: &mut Encoder) {
        e.u32(self.0);
    }
}
impl Encode for Bytes {
    fn encode(&self, e: &mut Encoder) {
        e.u32(self.address);
        e.u32(self.len);
    }
}
impl<T: Encode> Encode for Option<T> {
    fn encode(&self, e: &mut Encoder) {
        match self {
            Some(v) => {
                e.u8(1);
                v.encode(e);
            }
            None => e.u8(0),
        }
    }
}
impl<T: Encode> Encode for Vec<T> {
    fn encode(&self, e: &mut Encoder) {
        e.u32(self.len() as u32);
        for v in self {
            v.encode(e);
        }
    }
}
impl<T: Encode> Encode for (String, T) {
    fn encode(&self, e: &mut Encoder) {
        self.0.encode(e);
        self.1.encode(e);
    }
}

/// A reply's bytes, read back.
pub struct Decoder<'a> {
    bytes: &'a [u8],
    at: usize,
}

impl<'a> Decoder<'a> {
    pub fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, at: 0 }
    }
    fn take(&mut self, n: usize) -> Option<&'a [u8]> {
        let out = self.bytes.get(self.at..self.at + n)?;
        self.at += n;
        Some(out)
    }
    pub fn u8(&mut self) -> Option<u8> {
        Some(self.take(1)?[0])
    }
    pub fn u32(&mut self) -> Option<u32> {
        Some(u32::from_le_bytes(self.take(4)?.try_into().ok()?))
    }
}

/// A value read back from a reply.
pub trait Decode: Sized {
    fn decode(d: &mut Decoder) -> Option<Self>;
}

impl Decode for () {
    fn decode(_: &mut Decoder) -> Option<Self> {
        Some(())
    }
}
impl Decode for bool {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(d.u8()? != 0)
    }
}
impl Decode for String {
    fn decode(d: &mut Decoder) -> Option<Self> {
        let n = d.u32()? as usize;
        String::from_utf8(d.take(n)?.to_vec()).ok()
    }
}
impl Decode for Handle {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(Handle(d.u32()?))
    }
}
impl Decode for Bytes {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(Bytes {
            address: d.u32()?,
            len: d.u32()?,
        })
    }
}
impl<T: Decode> Decode for Option<T> {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(if d.u8()? != 0 {
            Some(T::decode(d)?)
        } else {
            None
        })
    }
}
impl<T: Decode> Decode for Vec<T> {
    fn decode(d: &mut Decoder) -> Option<Self> {
        (0..d.u32()?).map(|_| T::decode(d)).collect()
    }
}
impl<T: Decode> Decode for (String, T) {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some((String::decode(d)?, T::decode(d)?))
    }
}

/// `WebGLPowerPreference`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WebGLPowerPreference {
    /// `"default"`.
    Default,
    /// `"low-power"`.
    LowPower,
    /// `"high-performance"`.
    HighPerformance,
}

impl Encode for WebGLPowerPreference {
    fn encode(&self, e: &mut Encoder) {
        e.u32(*self as u32);
    }
}

impl WebGLPowerPreference {
    /// The value at `index` in the IDL's order.
    pub fn from_index(index: u32) -> Option<Self> {
        Some(match index {
            0 => Self::Default,
            1 => Self::LowPower,
            2 => Self::HighPerformance,
            _ => return None,
        })
    }
}

impl Decode for WebGLPowerPreference {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Self::from_index(d.u32()?)
    }
}

/// `WebGLContextAttributes`.
#[derive(Clone, Debug, PartialEq)]
pub struct WebGLContextAttributes {
    pub alpha: Option<bool>,
    pub depth: Option<bool>,
    pub stencil: Option<bool>,
    pub antialias: Option<bool>,
    pub premultiplied_alpha: Option<bool>,
    pub preserve_drawing_buffer: Option<bool>,
    pub power_preference: Option<WebGLPowerPreference>,
    pub fail_if_major_performance_caveat: Option<bool>,
    pub desynchronized: Option<bool>,
}

impl Encode for WebGLContextAttributes {
    fn encode(&self, e: &mut Encoder) {
        self.alpha.encode(e);
        self.depth.encode(e);
        self.stencil.encode(e);
        self.antialias.encode(e);
        self.premultiplied_alpha.encode(e);
        self.preserve_drawing_buffer.encode(e);
        self.power_preference.encode(e);
        self.fail_if_major_performance_caveat.encode(e);
        self.desynchronized.encode(e);
    }
}

impl Decode for WebGLContextAttributes {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(Self {
            alpha: Decode::decode(d)?,
            depth: Decode::decode(d)?,
            stencil: Decode::decode(d)?,
            antialias: Decode::decode(d)?,
            premultiplied_alpha: Decode::decode(d)?,
            preserve_drawing_buffer: Decode::decode(d)?,
            power_preference: Decode::decode(d)?,
            fail_if_major_performance_caveat: Decode::decode(d)?,
            desynchronized: Decode::decode(d)?,
        })
    }
}

/// A union: `Float32List`.
#[derive(Clone, Debug, PartialEq)]
pub enum Float32List {
    Bytes(Bytes),
    SequenceOfFloat(Vec<f32>),
}

impl Encode for Float32List {
    fn encode(&self, e: &mut Encoder) {
        match self {
            Self::Bytes(v) => {
                e.u8(0);
                v.encode(e);
            }
            Self::SequenceOfFloat(v) => {
                e.u8(1);
                v.encode(e);
            }
        }
    }
}

impl Decode for Float32List {
    fn decode(d: &mut Decoder) -> Option<Self> {
        Some(match d.u8()? {
            0 => Self::Bytes(Decode::decode(d)?),
            1 => Self::SequenceOfFloat(Decode::decode(d)?),
            _ => return None,
        })
    }
}

